      const newRow = [];
      for (let j = 0; j < thisShape[1]; j++) {
        newRow.push(this.get(i, j) + other.get(i, j));
      }
      resultRows.push(newRow);
    }

    return new Matrix(resultRows);
  }

  sub(other) {
    // Check if other is a Matrix
    if (!(other instanceof Matrix)) {
