    // If x is a number, perform scalar multiplication
    if (typeof x === 'number') {
      const resultRows = [];
      const shape = this.shape();
      for (let i = 0; i < shape[0]; i++) {
        const newRow = [];
        for (let j = 0; j < shape[1]; j++) {
          newRow.push(this.get(i, j) * x);
        }
